-- C-04 pending invoices. Preserve historical financial calculations and data.
set local lock_timeout='5s';set local statement_timeout='60s';
create schema pending_invoice_private;
revoke all on schema pending_invoice_private from public,anon,authenticated,service_role;
grant usage on schema pending_invoice_private to authenticated;
create function pending_invoice_private.allowed(resource text,a text) returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select asset_posting_private.allowed(resource,a)$$;
create function pending_invoice_private.access(resource text,a text) returns bigint language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select asset_posting_private.access(resource,a)$$;
create function pending_invoice_private.can_reverse() returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select pending_invoice_private.allowed('accounting:journals','edit') and exists(select 1 from public.user_roles ur join public.role_permissions rp using(role_id) join public.permissions p using(permission_id) where ur.user_id=public.app_user_id() and ur.role_id=public.app_active_role_id() and p.code='accounting:journal:reverse')$$;
create function pending_invoice_private.reversal_access() returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=asset_posting_private.identity();begin if not pending_invoice_private.can_reverse() then raise exception using errcode='42501',message='El rol activo no puede reversar pendientes.';end if;return sid;end$$;
create function pending_invoice_private.reclass_context() returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=asset_posting_private.identity();begin if not(pending_invoice_private.allowed('accounting:pending-invoice-reclassification','view')or pending_invoice_private.allowed('accounting:pending-invoice-reclassification','create')) then raise exception using errcode='42501',message='Sin acceso a reclasificaciones.';end if;return sid;end$$;
create function pending_invoice_private.source(id bigint,locking boolean default false) returns bigint language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=pending_invoice_private.reversal_access();j public.journal;i public.opening_pending_invoice_items;r public.opening_balance_runs;begin
 if id is null or id=0 or id='-9223372036854775808'::bigint then raise exception using errcode='22023',message='Origen inválido.';end if;
 if locking then perform pg_advisory_xact_lock(hashtextextended('fx-subsidiary:'||sid,0));perform pg_advisory_xact_lock(hashtextextended('pending-invoice-reclassification-subsidiary:'||sid,0));end if;
 if id>0 then
  select * into j from public.journal where journal_id=$1 and subsidiary_id=sid;
  if not found or j.journal_type<>'Asientos Pendientes de Facturar' or j.status<>'CONTABILIZADO' then raise exception using errcode='42501',message='Pendiente no disponible.';end if;
  if locking then perform 1 from public.journal where journal_id=id for update;end if;
 else
  select * into i from public.opening_pending_invoice_items where opening_pending_invoice_items.id=-$1 and subsidiary_id=sid;
  if not found then raise exception using errcode='42501',message='Pendiente no disponible.';end if;
  if locking then select * into r from public.opening_balance_runs where opening_balance_runs.id=i.run_id and subsidiary_id=sid for update;perform 1 from public.opening_pending_invoice_items where opening_pending_invoice_items.id=i.id for update;
  else select * into r from public.opening_balance_runs where opening_balance_runs.id=i.run_id and subsidiary_id=sid;end if;
  if r.id is null or r.status<>'POSTED' or not i.is_active or i.opening_reversed_at is not null then raise exception using errcode='55000',message='El pendiente inicial no está activo.';end if;
 end if;return sid;end$$;
create function pending_invoice_private.validate_payload(id bigint,p jsonb) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=pending_invoice_private.source(id,true);amount numeric;d date;origin_date date;begin
 if jsonb_typeof(p) is distinct from 'object' then raise exception using errcode='22023',message='Datos de reversión inválidos.';end if;
 amount:=nullif(p->>'amount','')::numeric;d:=nullif(p->>'reversalDate','')::date;
 if amount is null or amount<=0 or amount::text in('NaN','Infinity','-Infinity') or d is null or d>current_date or coalesce(p->>'type','') not in('FACTURACION','ERROR_CORRECCION') then raise exception using errcode='22023',message='Revise monto, fecha y tipo de reversión.';end if;
 if id>0 then select journal_date into origin_date from public.journal where journal_id=id;else select r.opening_date into origin_date from public.opening_pending_invoice_items i join public.opening_balance_runs r on r.id=i.run_id where i.id=-$1;end if;
 if d<origin_date or(id<0 and d=origin_date) then raise exception using errcode='22023',message='La fecha de reversión no corresponde al origen.';end if;
 if not exists(select 1 from public.fiscal_periods where subsidiary_id=sid and d between start_date and end_date and not coalesce(is_closed,false) and not coalesce(gl_closed,false) and not coalesce(is_inactive,false) and (p->>'type'<>'FACTURACION' or not coalesce(ar_closed,false))) then raise exception using errcode='55000',message='El período de reversión está cerrado.';end if;
end$$;
create function pending_invoice_private.check_journal(id bigint) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare j public.journal;debits numeric;credits numeric;begin
 select * into j from public.journal where journal_id=id and subsidiary_id=asset_posting_private.identity();
 if not found or j.transaction_id is null or j.status<>'CONTABILIZADO' or not asset_posting_private.finite(j.total_debit) or j.total_debit<=0 or abs(j.total_debit-j.total_credit)>.005 then raise exception using errcode='55000',message='No se confirmó un asiento equilibrado.';end if;
 select sum(debit_amount),sum(credit_amount) into debits,credits from public.gl_impact where transaction_id=j.transaction_id;
 if not asset_posting_private.finite(debits) or not asset_posting_private.finite(credits) or abs(debits-credits)>.005 or abs(debits-j.total_debit)>.005 then raise exception using errcode='55000',message='El mayor no corresponde al asiento.';end if;
end$$;
do $$declare sig text;begin foreach sig in array array['pending_invoice_control_options()','run_pending_invoice_control_report(jsonb)','pending_invoice_reversal_options(bigint,date)','opening_pending_invoice_reversal_options(bigint,date)','reverse_pending_invoice_journal(bigint,jsonb)','reverse_opening_pending_invoice(bigint,jsonb)','pending_invoice_reclassification_preview(date)','pending_invoice_reclassification_execute(date)']loop execute format('alter function public.%s set schema pending_invoice_private',sig);end loop;end$$;
-- A creator can inspect the same bounded preview needed to execute its own action.
do $$declare body text;begin body:=pg_get_functiondef('pending_invoice_private.pending_invoice_reclassification_preview(date)'::regprocedure);
 body:=regexp_replace(body,'perform public.security_assert_role_access\(\s*''accounting:pending-invoice-reclassification'',''view''\s*\);','perform pending_invoice_private.reclass_context();');execute body;end$$;
create function public.pending_invoice_control_options() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=pending_invoice_private.access('reports:accounting-reports','view');result jsonb;begin
 result:=pending_invoice_private.pending_invoice_control_options();
 return result||jsonb_build_object('canReverse',pending_invoice_private.can_reverse(),'canReclassify',pending_invoice_private.allowed('accounting:pending-invoice-reclassification','create'),'canViewReclassification',pending_invoice_private.allowed('accounting:pending-invoice-reclassification','view')or pending_invoice_private.allowed('accounting:pending-invoice-reclassification','create'),'customers',coalesce((select jsonb_agg(jsonb_build_object('id',c.customer_id,'name',c.company_name) order by c.company_name) from public.customers c where c.primary_subsidiary_id=sid or exists(select 1 from public.entity_subsidiaries e where e.customer_id=c.customer_id and e.subsidiary_id=sid)),'[]'::jsonb));end$$;
create function public.run_pending_invoice_control_report(p_filters jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=pending_invoice_private.access('reports:accounting-reports','view');begin
 if coalesce((p_filters->>'consolidated')::boolean,false) then perform consolidation_private.assert_scope(to_char(coalesce(nullif(p_filters->>'dateTo','')::date,current_date),'YYYY-MM'));
 else
  if p_filters?'subsidiaryIds' and exists(select 1 from jsonb_array_elements_text(p_filters->'subsidiaryIds')x where x::bigint<>sid) then raise exception using errcode='42501',message='Active la filial que desea consultar.';end if;
  if nullif(p_filters->>'subsidiaryId','') is not null and (p_filters->>'subsidiaryId')::bigint<>sid then raise exception using errcode='42501',message='Filial no disponible.';end if;
  p_filters:=p_filters||jsonb_build_object('subsidiaryIds',jsonb_build_array(sid),'subsidiaryId',sid);
 end if;return pending_invoice_private.run_pending_invoice_control_report(p_filters);end$$;
create function public.pending_invoice_reversal_options(p_journal_id bigint,p_reversal_date date) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform pending_invoice_private.source(p_journal_id);return pending_invoice_private.pending_invoice_reversal_options(p_journal_id,p_reversal_date);end$$;
create function public.opening_pending_invoice_reversal_options(p_item_id bigint,p_reversal_date date) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_item_id is null or p_item_id<=0 then raise exception using errcode='22023',message='Origen inválido.';end if;perform pending_invoice_private.source(-p_item_id);return pending_invoice_private.opening_pending_invoice_reversal_options(p_item_id,p_reversal_date);end$$;
create function public.reverse_pending_invoice_journal(p_journal_id bigint,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare result jsonb;begin perform pending_invoice_private.validate_payload(p_journal_id,p_payload);result:=pending_invoice_private.reverse_pending_invoice_journal(p_journal_id,p_payload);perform pending_invoice_private.check_journal((result->>'journalId')::bigint);return result;end$$;
create function public.reverse_opening_pending_invoice(p_item_id bigint,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare result jsonb;begin if p_item_id is null or p_item_id<=0 then raise exception using errcode='22023',message='Origen inválido.';end if;perform pending_invoice_private.validate_payload(-p_item_id,p_payload);result:=pending_invoice_private.reverse_opening_pending_invoice(p_item_id,p_payload);perform pending_invoice_private.check_journal((result->>'journalId')::bigint);return result;end$$;
create function public.pending_invoice_reclassification_preview(p_reclassification_date date) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=pending_invoice_private.reclass_context();result jsonb;can_create boolean:=pending_invoice_private.allowed('accounting:pending-invoice-reclassification','create');begin result:=pending_invoice_private.pending_invoice_reclassification_preview(p_reclassification_date);return result||jsonb_build_object('canCreate',can_create,'canExecute',coalesce((result->>'canExecute')::boolean,false)and can_create);end$$;
create function public.pending_invoice_reclassification_execute(p_reclassification_date date) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=pending_invoice_private.access('accounting:pending-invoice-reclassification','create');result jsonb;j jsonb;begin
 perform pg_advisory_xact_lock(hashtextextended('fx-subsidiary:'||sid,0));result:=pending_invoice_private.pending_invoice_reclassification_execute(p_reclassification_date);
 for j in select value from jsonb_array_elements(coalesce(result->'journals','[]'::jsonb))loop perform pending_invoice_private.check_journal((j->>'journalId')::bigint);end loop;return result;end$$;
create function pending_invoice_private.reversal_visible(id bigint) returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select pending_invoice_private.allowed('reports:accounting-reports','view') and exists(select 1 from public.pending_invoice_reversal r left join public.journal j on j.journal_id=r.source_journal_id left join public.opening_pending_invoice_items i on i.id=r.source_opening_pending_id where r.reversal_id=$1 and coalesce(j.subsidiary_id,i.subsidiary_id)=asset_posting_private.identity())$$;
create function pending_invoice_private.reclass_visible(sid bigint) returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select $1=asset_posting_private.identity() and (pending_invoice_private.allowed('accounting:pending-invoice-reclassification','view')or pending_invoice_private.allowed('reports:accounting-reports','view'))$$;
do $$declare t text;p record;c record;f record;body text;begin
 foreach t in array array['pending_invoice_reversal','pending_invoice_reclassification_runs','pending_invoice_reclassification_items']loop
  execute format('alter table public.%I enable row level security',t);for p in select policyname from pg_policies where schemaname='public'and tablename=t loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;
  execute format('create policy pending_secure_read on public.%I for select to authenticated using(%s)',t,case when t='pending_invoice_reversal'then'pending_invoice_private.reversal_visible(reversal_id)'else'pending_invoice_private.reclass_visible(subsidiary_id)'end);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
  for c in select column_name from information_schema.columns where table_schema='public'and table_name=t loop execute format('revoke insert(%I),update(%I),references(%I),select(%I) on public.%I from public,anon,authenticated,service_role',c.column_name,c.column_name,c.column_name,c.column_name,t);end loop;
  execute format('grant select on public.%I to authenticated',t);
 end loop;
 for f in select pf.oid::regprocedure signature from pg_proc pf join pg_namespace n on n.oid=pf.pronamespace where n.nspname='public' and pf.prorettype<>'trigger'::regtype and(pf.proname like 'pending_invoice_%'or pf.proname like 'reverse_pending_invoice_%'or pf.proname like 'reverse_opening_pending_%'or pf.proname like 'run_pending_invoice_%'or pf.proname in('save_pending_reversal_supports','validate_pending_reversal_supports')) and pf.proname not in('pending_invoice_control_options','run_pending_invoice_control_report','pending_invoice_reversal_options','reverse_pending_invoice_journal','reverse_opening_pending_invoice','pending_invoice_reclassification_preview','pending_invoice_reclassification_execute')loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);end loop;
 body:=pg_get_functiondef('public.accounting_report_options_bundle()'::regprocedure);
 body:=replace(body,$n$coalesce(public.pending_invoice_control_options(),'{}'::jsonb)$n$,$r$coalesce(case when pending_invoice_private.allowed('reports:accounting-reports','view')then public.pending_invoice_control_options()else '{}'::jsonb end,'{}'::jsonb)$r$);execute body;
end$$;
revoke all on all functions in schema pending_invoice_private from public,anon,authenticated,service_role;
grant execute on function pending_invoice_private.reversal_visible(bigint),pending_invoice_private.reclass_visible(bigint) to authenticated;
revoke all on function public.pending_invoice_control_options(),public.run_pending_invoice_control_report(jsonb),public.pending_invoice_reversal_options(bigint,date),public.opening_pending_invoice_reversal_options(bigint,date),public.reverse_pending_invoice_journal(bigint,jsonb),public.reverse_opening_pending_invoice(bigint,jsonb),public.pending_invoice_reclassification_preview(date),public.pending_invoice_reclassification_execute(date) from public,anon,authenticated,service_role;
grant execute on function public.pending_invoice_control_options(),public.run_pending_invoice_control_report(jsonb),public.pending_invoice_reversal_options(bigint,date),public.opening_pending_invoice_reversal_options(bigint,date),public.reverse_pending_invoice_journal(bigint,jsonb),public.reverse_opening_pending_invoice(bigint,jsonb),public.pending_invoice_reclassification_preview(date),public.pending_invoice_reclassification_execute(date) to authenticated;
notify pgrst,'reload schema';
